create or replace function public.crm_record_channel_delivery_status(p_channel_account_id uuid,p_external_message_id text,p_status text,p_provider_event jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare n int:=0; begin if p_channel_account_id is null or nullif(trim(p_external_message_id),'') is null then raise exception 'invalid_delivery_status'; end if; if p_status not in ('queued','sent','delivered','read','failed') then raise exception 'invalid_delivery_status_value'; end if; update public.crm_channel_message_outbox set status=case when p_status='failed' then 'failed' when p_status in ('sent','delivered','read') then 'sent' else status end, external_message_id=p_external_message_id, failed_at=case when p_status='failed' then now() else failed_at end, sent_at=case when p_status in ('sent','delivered','read') then coalesce(sent_at,now()) else sent_at end, last_error=case when p_status='failed' then coalesce(p_provider_event->>'error','provider_delivery_failed') else null end, metadata=metadata||jsonb_build_object('delivery_status',p_status,'provider_event',p_provider_event),updated_at=now() where channel_account_id=p_channel_account_id and external_message_id=p_external_message_id; get diagnostics n=row_count; update public.crm_messages set delivered_at=case when p_status in ('delivered','read') then coalesce(delivered_at,now()) else delivered_at end, metadata=metadata||jsonb_build_object('delivery_status',p_status,'provider_event',p_provider_event) where channel_account_id=p_channel_account_id::text and external_message_id=p_external_message_id; return jsonb_build_object('updated_outbox_rows',n,'status',p_status); end; $$; revoke all on function public.crm_record_channel_delivery_status(uuid,text,text,jsonb) from public,anon,authenticated; grant execute on function public.crm_record_channel_delivery_status(uuid,text,text,jsonb) to service_role;
